<section class="ios-card overflow-hidden"><div class="card-heading"><div><h2>Historial de mediciones</h2><p><?= count($indicators) ?> registros consolidados.</p></div></div><?php if ($indicators === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('chart', 'h-7 w-7') ?></span><h3>Aún no hay mediciones</h3><p>Registra el primer indicador para iniciar el seguimiento.</p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Indicador</th><th>Periodo</th><th>Datos fuente</th><th>Resultado</th><th>Meta</th><th>Corte</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><?php foreach ($indicators as $indicator): ?><tr id="indicador-<?= (int) $indicator['id'] ?>"><td><p class="max-w-[250px] text-xs font-semibold leading-5 text-slate-700"><?= e($indicator['nombre']) ?></p><span class="badge badge-gray mt-1.5"><?= e($indicator['tipo']) ?></span><?php if($indicator['verificado_at']): ?><span class="badge badge-green mt-1">Fuentes verificadas</span><?php else: ?><span class="badge badge-gray mt-1">Verificación pendiente</span><?php endif; ?><div class="mt-2 flex flex-wrap gap-2"><a href="<?= e(url('/evidencias?vinculo=' . rawurlencode('indicador:' . $indicator['id']) . '#cargar')) ?>" class="text-[10px] font-medium text-blue-600">Soportes</a><?php if(!$indicator['verificado_at']): ?><form method="post" action="<?= e(url('/indicadores/' . $indicator['id'] . '/verificar')) ?>"><?= csrf_field() ?><button class="text-[10px] font-medium text-blue-600" type="submit">Verificar fuentes</button></form><?php endif; ?></div></td><td class="text-xs text-slate-600"><?= e($indicator['periodo']) ?></td><td><p class="whitespace-nowrap font-mono text-[10px] text-slate-500"><?php if($indicator['tipo']==='Presentismo'): ?>(<?= e($indicator['denominador']) ?> − <?= e($indicator['numerador']) ?>) × <?= e($indicator['factor']) ?> ÷ <?= e($indicator['denominador']) ?><?php else: ?><?= e($indicator['numerador']) ?> × <?= e($indicator['factor']) ?> ÷ <?= e($indicator['denominador']) ?><?php endif; ?></p><p class="mt-1 max-w-[230px] text-[9px] leading-4 text-slate-400">N: <?= e($indicator['fuente_numerador'] ?: 'Sin fuente') ?><br>D: <?= e($indicator['fuente_denominador'] ?: 'Sin fuente') ?></p></td><td><p class="text-lg font-semibold tracking-tight text-blue-600"><?= e($indicator['resultado']) ?></p><p class="mt-0.5 max-w-[130px] text-[9px] leading-3 text-slate-400"><?= e($indicator['unidad']) ?></p><?php if($indicator['anterior_resultado']!==null): ?><p class="mt-2 text-[10px] text-slate-500">Anterior: <?= e($indicator['anterior_resultado']) ?> · Δ <?= $indicator['variacion']>0?'+':'' ?><?= e($indicator['variacion']) ?></p><?php endif; ?><?php if($indicator['referencia_valor']!==null): ?><p class="mt-1 max-w-44 text-[10px] text-slate-500">Referencia: <?= e($indicator['referencia_valor']) ?> · Δ <?= $indicator['referencia_diferencia']>0?'+':'' ?><?= e($indicator['referencia_diferencia']) ?><br><span class="text-slate-400"><?= e($indicator['referencia_periodo']) ?> · <?= e($indicator['referencia_fuente']) ?></span></p><?php endif; ?></td><td class="text-xs text-slate-500"><?= $indicator['meta'] !== null ? e($indicator['meta']) : 'Sin meta' ?></td><td><time class="whitespace-nowrap text-xs text-slate-500"><?= format_date($indicator['fecha_corte']) ?></time></td><td><div class="flex gap-1"><a href="<?= e(url('/indicadores/' . $indicator['id'] . '/editar')) ?>" class="btn-ghost h-8 px-2" aria-label="Editar medición"><?= icon('edit', 'h-4 w-4') ?></a><form method="post" action="<?= e(url('/indicadores/' . $indicator['id'] . '/eliminar')) ?>" data-confirm="¿Eliminar esta medición? La acción quedará auditada."><?= csrf_field() ?><button type="submit" class="btn-ghost h-8 px-2 text-rose-600" aria-label="Eliminar medición"><?= icon('x', 'h-4 w-4') ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
